INSERT INTO consentimiento_plantillas (codigo, nombre, texto, riesgos, beneficios, alternativas, requiere_testigo, vigencia_dias, version, activa) VALUES
    ('ANESTESIA_LOCAL', 'Anestesia local',
     'Se aplicará un anestésico local en la zona del procedimiento para eliminar el dolor mientras este se realiza. Usted permanecerá despierto y podrá comunicarse con el equipo médico.',
     'Reacción alérgica al anestésico, enrojecimiento o hematoma en el sitio de la inyección, adormecimiento prolongado y, de manera infrecuente, toxicidad por el anestésico.',
     'Permite realizar el procedimiento sin dolor y con una recuperación más rápida que una anestesia general.',
     'Realizar el procedimiento sin anestesia, usar anestesia regional o general según la indicación del médico.',
     false, 30, 1, true),
    ('PEQUENA_CIRUGIA', 'Pequeña cirugía ambulatoria',
     'Procedimiento quirúrgico menor realizado en consultorio o sala de procedimientos, con anestesia local, para extirpar o tratar una lesión de piel o tejido blando.',
     'Sangrado, infección de la herida, cicatriz visible o queloide, recurrencia de la lesión, lesión de estructuras vecinas y dehiscencia de la sutura.',
     'Eliminar o diagnosticar la lesión, aliviar los síntomas y enviar el tejido a estudio cuando corresponde.',
     'Observación y control periódico, tratamiento médico o derivación a un establecimiento de mayor complejidad.',
     true, 30, 1, true),
    ('ENDOSCOPIA', 'Endoscopía digestiva',
     'Examen en el que se introduce un tubo flexible con una cámara por la boca o el recto para observar el tubo digestivo y tomar muestras si es necesario.',
     'Molestias en la garganta o el abdomen, sangrado leve tras una biopsia, reacción a la sedación y, muy raramente, perforación del tubo digestivo.',
     'Permite diagnosticar enfermedades digestivas y tratar algunas lesiones en el mismo acto.',
     'Estudios de imagen como la ecografía o la tomografía, o tratamiento empírico según el criterio médico.',
     true, 15, 1, true),
    ('TRANSFUSION', 'Transfusión de sangre y hemoderivados',
     'Administración de sangre o de alguno de sus componentes para reponer lo perdido o tratar una enfermedad de la sangre.',
     'Fiebre, escalofríos, reacciones alérgicas, reacción hemolítica, sobrecarga de líquidos y, muy raramente, transmisión de infecciones a pesar de los controles.',
     'Corrige la anemia o la falta de factores de coagulación y puede salvar la vida en una hemorragia grave.',
     'Tratamiento con hierro o medicamentos, expansores de volumen, o conducta expectante cuando el cuadro lo permite.',
     true, 7, 1, true),
    ('PROCEDIMIENTO_INVASIVO', 'Procedimiento invasivo diagnóstico o terapéutico',
     'Procedimiento que requiere la punción o la introducción de instrumentos en el cuerpo, como una punción lumbar, una toracocentesis o una paracentesis, realizado con técnica estéril.',
     'Dolor, sangrado, infección, lesión de órganos vecinos, reacción a los medicamentos y la necesidad de repetir el procedimiento.',
     'Obtener un diagnóstico preciso o aliviar los síntomas al drenar líquido acumulado.',
     'Observación, estudios de imagen no invasivos o tratamiento médico sin el procedimiento.',
     false, 15, 1, true),
    ('HOSPITALIZACION', 'Hospitalización y tratamiento hospitalario',
     'Ingreso al hospital para observación, estudios y tratamiento que no pueden realizarse de forma ambulatoria, con atención del equipo médico y de enfermería las 24 horas.',
     'Infecciones asociadas a la atención, reacciones a los medicamentos, caídas, complicaciones propias de la enfermedad y efectos de los procedimientos que se indiquen.',
     'Vigilancia continua, acceso inmediato a tratamientos y estudios, y respuesta rápida ante cualquier complicación.',
     'Tratamiento ambulatorio con controles frecuentes o atención domiciliaria cuando el cuadro lo permite.',
     false, 60, 1, true);
